function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function visited(p){return !!p&&heat.pieces.some(s=>distance(p,s.p)<80);}
function placeList(){return allPlaces().filter(p=>(category==='all'||p.category===category||(category==='ghost'&&p.haunted))&&(!reviewsOnly||p.reviews?.length)&&(!onlyStories||(['ghost','rumor','history'].includes(p.category)&&(!p.pos||p.area?.includes('岩倉')||distance(p.pos,home().pos)<4000)))&&placeMatch(p,query).score>0&&(!onlyNew||!visited(p.pos))&&(tab!=='saved'||data.bookmarks.includes(p.id))).sort((a,b)=>{const score=placeMatch(b,query).score-placeMatch(a,query).score;if(query&&score)return score;const c=[map.getCenter().lat,map.getCenter().lng];return (a.pos?distance(a.pos,c):Infinity)-(b.pos?distance(b.pos,c):Infinity);});}

function renderStats(){const walks=actualWalks();return `<div class="stats"><div class="stat"><label>歩いた距離${demo?'（例）':''}</label><strong>${km(walks.reduce((s,w)=>s+pathLength(w.points),0))}</strong><small>km</small></div><div class="stat"><label>散歩・通勤${demo?'（例）':''}</label><strong>${walks.length}</strong><small>回</small></div><div class="stat"><label>記録の近く${demo?'（例）':''}</label><strong>${allPlaces().filter(p=>visited(p.pos)).length}</strong><small>か所</small></div></div>`;}
