function renderListOnly(){if($('#search-support'))$('#search-support').innerHTML=searchSupport();const list=placeList();$('#story-count').textContent=`${list.length}件`;$('#story-list').innerHTML=list.length?list.map(card).join(''):'<div class="empty">該当する場所がありません。<br>検索する言葉を変えてみてください。</div>';}
function renderHeat(){heatLayer.clearLayers();heat=heatData(actualWalks());if(showHeat){const groups=new Map();for(const s of heat.pieces){const n=heat.cells.get(s.key);if(!groups.has(n))groups.set(n,[]);groups.get(n).push([s.p,s.q]);}for(const [n,paths]of groups){L.polyline(paths,{color:'#fff',weight:10,opacity:.95,interactive:false}).addTo(heatLayer);L.polyline(paths,{color:colorFor(n),weight:6.5,opacity:onlyNew?.25:1,lineCap:'round'}).bindTooltip(`${demo?'サンプル · ':''}この付近を通った記録：${n}回`).addTo(heatLayer);}}}
function renderPins(){pinLayer.clearLayers();for(const p of placeList()){if(!p.pos||p.id===WORKPLACE.id)continue;const marker=L.marker(p.pos,{icon:L.divIcon({className:'place-marker',html:`<div class="map-pin ${p.category}${p.kind?' pin-'+p.kind:''}${p.positionConfidence==='unverified'?' uncertain-pin':''}">${p.positionConfidence==='unverified'&&!p.kind?'<span>?</span>':icon(p.icon||categories[p.category]?.icon||'chat')}</div>`,iconSize:[35,35],iconAnchor:[17,17]}),title:(p.place||p.title)+(p.positionConfidence==='unverified'?' · 位置未確認':''),keyboard:true}).bindTooltip(esc((p.place||p.title)+(p.positionConfidence==='unverified'?' · 位置未確認':'')),{direction:'top',offset:[0,-18]});marker.on('click',()=>{if(!recording||recording.auto){visitPlace(p.id);hideMobile();}});marker.addTo(pinLayer);}}
function refresh(){renderHeat();renderPins();renderSidebar();renderHomePin();$('#sample-banner').hidden=!demo;$('#heat-toggle').classList.toggle('active',showHeat);$('#heat-toggle').setAttribute('aria-pressed',showHeat);$('#discover-toggle').classList.toggle('active',onlyNew);$('#discover-toggle').setAttribute('aria-pressed',onlyNew);}
function openPlace(id){const p=allPlaces().find(p=>p.id===id);if(!p)return;selected=id;const c=categories[p.category]||categories.rumor;$('#detail').hidden=false;$('#detail').innerHTML=`<button class="close" data-action="close-detail" aria-label="閉じる">${icon('close')}</button><div class="detail-art ${p.category}${p.kind?' art-'+p.kind:''}">${icon(p.icon||c.icon)}</div><span class="eyebrow">${esc(p.kicker||'自分のメモ')}</span><h2>${esc(p.title)}</h2><span class="place">${c.label} · ${esc(p.place)} · ${!p.pos?'所在地未確認':visited(p.pos)?'記録の近く':'未探索（記録なし）'}</span>${p.positionLabel?`<p class="position-evidence ${p.positionConfidence==='unverified'?'position-unverified':''}">${esc(p.positionLabel)}</p>`:''}<div class="detail-body">${esc(p.body)}</div>${p.category==='shop'?shopControls(p):''}${p.kind==='conbini'?`<button class="secondary conbini-menu" data-conbini-open="${/ローソン/.test(p.title)?'lawson':/セブン/.test(p.title)?'seven':'famima'}">この店の成分表を見る・記録する</button>`:''}${reviewsMarkup(p,esc)}${p.encounter?'<button class="encounter-button" data-action="battle">⚔ バトルで遊ぶ</button>':''}<div class="detail-note">${esc(p.note)}</div>${p.url?`<a class="source-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">出典：${esc(p.source)} ↗</a><div class="checked">${p.external?'地図検索で取得':'情報確認：2026年10月28日'}${p.pos?' · ピンは所在地の目安':''}</div>`:`<div class="checked">${esc(p.source||'自分のメモ')} · 非公開</div>`}${p.visitReportUrl?`<a class="source-link" href="${esc(p.visitReportUrl)}" target="_blank" rel="noopener noreferrer">2026年4月の現地訪問記 ↗</a>`:''}${p.referenceUrl?`<a class="source-link" href="${esc(p.referenceUrl)}" target="_blank" rel="noopener noreferrer">${esc(p.referenceLabel)} ↗</a><p class="reference-note">${esc(p.referenceNote)}</p>`:''}${p.positionSource?`<a class="position-source" href="${esc(p.positionSource)}" target="_blank" rel="noopener noreferrer">地図位置の出典 ↗</a>`:''}<div class="button-row"><button class="secondary" data-bookmark="${esc(id)}">${icon('bookmark')}${data.bookmarks.includes(id)?'保存を解除':'保存する'}</button>${p.pos?`<button class="primary" data-focus="${esc(id)}">${icon('location')}地図で見る</button>`:''}</div>${p.id===WORKPLACE.id?'<div class="button-row"><button class="text-btn" data-action="go-work">職場の周辺を見る</button></div><details class="goat-extra"><summary>おまけ</summary><p>仕事の愚痴をヤギに食べてもらえます。</p><button class="secondary" data-action="goat">ヤギを呼ぶ</button></details>':''}${p.personal?`<div class="button-row"><button class="text-btn" data-delete-note="${esc(id)}">このメモを削除</button></div>`:''}`;}
function visitPlace(id){openPlace(id);const p=allPlaces().find(p=>p.id===id);if(p?.encounter&&data.battleEffects!==false&&(!recording||recording.auto))openBattle(id==='jiro-kyoto'?'ramen':'salary',id==='jiro-kyoto');}
