function gymCard(){const w=gymWeek(data.shopVisits,jstDay(),data.gymGoal||2),c=jstDay(),dow=(new Date(c+'T00:00:00Z').getUTCDay()+6)%7;return '<button class="gym-card'+(w.done?' gym-done':dow>=3&&!w.done?' gym-nudge':'')+'" data-place="'+GYM.id+'">'+icon('dumbbell')+'<span><strong>運動ノルマ 今週 '+w.count+'/'+w.goal+'</strong><small>'+(w.done?'達成。'+esc(data.pet.name)+'も引き締まった':dow>=3?'あと'+w.left+'回。行くと'+esc(data.pet.name)+'がやせる':'ジムに行くと'+esc(data.pet.name)+'がやせる')+'</small></span><i>'+'●'.repeat(w.count)+'○'.repeat(w.left)+'</i></button>';}
