let dayContext=null;dayContext=installDayContext({getNutrition:()=>data.nutrition,esc,toast,getEvening:eveningView,onDinnerPrompt:()=>play('dinner'),onPlan:id=>{play('pop');if(data.pet.travel.state==='home'){data.pet=hopeFor(data.pet,id);save();setTimeout(()=>toast(data.pet.name+'が台所のほうを見ている。おこぼれ待ち。'),1400);}}});
