function eveningState(){return normalizeEvening(data.evening,jstDay());}
function kmToday(){const day=jstDay();let m=0;for(const w of data.walks){const t=w.points?.at(-1)?.[2];if(Number.isFinite(t)&&dayKey(t)===day)m+=pathLength(w.points);}if(recording?.points?.length)m+=pathLength(recording.points);return m/1000;}
function walkedToday(){return kmToday()>0.3;}
function eveningView(){const day=jstDay(),ev=eveningState(),c=japanClock(),w=dayContext?.getWeather?.(),tonight=w?.tonightMin??null,blanket=normalizeBlanket(data.blanket);
 if(ev.cameHome&&!ev.dismissed){const allDone=EVENING_STEPS.every(([k])=>ev.steps[k]),next=EVENING_STEPS.find(([k])=>!ev.steps[k]);return {greeted:true,markup:eveningMarkup({ev,blanket,day,time:japanClock(ev.cameHome).time,tonight,kmToday:kmToday(),esc}),dock:{title:'おつかれさま！'+(allDone?' おやすみ':' お風呂 → ご飯 → ゆっくり'),sub:next?'つぎは'+next[1]+(Number.isFinite(tonight)?' · 今夜 '+tonight+'°':''):'今日はもう十分。'}};}
 if(ev.cameHome)return {greeted:true,markup:isEveningHour(c.hour)?blanketMarkup({blanket,day,tonight,esc,compact:true}):'',dock:null};
 return {greeted:false,markup:isEveningHour(c.hour)?blanketMarkup({blanket,day,tonight,esc,compact:true}):'',dock:null};}
function greet(source,now=Date.now()){const ev=eveningState();if(ev.cameHome&&!ev.dismissed)return;data.evening={...ev,cameHome:now,dismissed:false,source};if(!save())return;dayContext.paint();if(tab==='home')$('#sidebar-content').scrollTop=0;play('chime');toast('おかえりなさい');}
