try{const response=await fetch('kyoto.json');if(!response.ok)throw Error();boundary=await response.json();let draft=null;try{draft=JSON.parse(localStorage.getItem(KEY+'-draft')||'null');}catch{}if(draft?.auto){data.walks=commitAutoWalk(data.walks,draft);save();localStorage.removeItem(KEY+'-draft');draft=null;}if(draft?.points?.length>=2){modal(`<h2>保存前の記録があります</h2><p>前回保存していない ${km(pathLength(draft.points))} km の軌跡を復元できます。</p><div class="button-row"><button id="discard-draft" class="secondary">破棄する</button><button id="restore-draft" class="primary">復元する</button></div>`);$('#discard-draft').onclick=()=>{localStorage.removeItem(KEY+'-draft');closeModal();};$('#restore-draft').onclick=()=>{closeModal();demo=false;recording={...draft,paused:true,status:'前回の軌跡を復元しました。保存できます。'};$('.map-bottom').hidden=true;$('#mobile-sidebar').hidden=true;refresh();renderDraft();map.fitBounds(recording.points.map(p=>p.slice(0,2)),{padding:[60,60],maxZoom:16});};}if(!draft&&data.autoTrack&&data.autoTrackConsent)startAutoTrack();}catch{toast('京都府の境界を読み込めません。再読み込みしてください。記録機能は一時停止しています。');}

function shops(){return allPlaces().filter(p=>p.category==='shop'&&p.pos);}
function frequentIds(){return frequentShopIds(data.shopVisits,data.pinnedShops,data.dismissedShops);}
function fromHome(p){if(!p.pos)return '所在地未確認';const d=distance(home().pos,p.pos);return `自宅から直線 ${d<1000?Math.round(d/10)*10+' m':(d/1000).toFixed(1)+' km'}`;}
function shopCard(p,frequent=false){const n=visitCount(data.shopVisits,p.id);return `<button class="home-shop" data-place="${esc(p.id)}"><span class="shop-avatar ${p.id==='mcd-takaragaike'?'mcd':p.kind?'av-'+p.kind:''}">${p.id==='mcd-takaragaike'?'M':icon(p.icon||'cup')}</span><span><strong>${esc(p.place||p.title)}</strong><small>${esc(data.shopMemos[p.id]||p.defaultMemo||(n?`${n}日分の訪問記録`:'気になったら登録できます'))}</small><em>${esc(fromHome(p))}${frequent?` · ${n}日訪問`:''}</em></span>${icon('chevron')}</button>`;}
function renderHome(){const list=shops().filter(p=>p.kind!=='gym'),ids=frequentIds(),frequent=list.filter(p=>ids.includes(p.id)).sort((a,b)=>visitCount(data.shopVisits,b.id)-visitCount(data.shopVisits,a.id));const nearby=list.filter(p=>!ids.includes(p.id)).sort((a,b)=>(a.id==='mcd-takaragaike'?-1:b.id==='mcd-takaragaike'?1:distance(a.pos,home().pos)-distance(b.pos,home().pos))).slice(0,3);return homeMarkup({dayContext:dayContext.markup(),extra:autoHome()+gymCard()+installCard(),home:home(),family:FAMILY,icon,esc,stats:renderStats(),frequent,nearby,auto:data.autoShops,shopCard});}
function renderHomePin(){if(!workMarker)workMarker=L.marker(WORKPLACE.pos,{icon:L.divIcon({className:'home-map-marker work-map-marker',html:`<span>${icon('building')}</span><strong>銀くんの職場</strong>`,iconSize:[76,60],iconAnchor:[38,24]}),title:'銀くんの勤務先・至誠館4階（大学代表位置）',zIndexOffset:900}).addTo(map).on('click',()=>{if(!recording||recording.auto){visitPlace(WORKPLACE.id);hideMobile();}});if(homeMarker){homeMarker.setLatLng(home().pos);return;}homeMarker=L.marker(home().pos,{icon:L.divIcon({className:'home-map-marker',html:`<span>${icon('home')}</span><strong>睦荘</strong>`,iconSize:[54,60],iconAnchor:[27,24]}),title:'自宅・睦荘',zIndexOffset:1000}).addTo(map).on('click',()=>{if(!recording||recording.auto){tab='home';renderSidebar();document.body.classList.add('mobile-show');}});}
