function shopControls(p){const n=visitCount(data.shopVisits,p.id),today=dayKey(Date.now()),already=data.shopVisits.some(v=>v.shopId===p.id&&v.day===today),frequent=frequentIds().includes(p.id);if(p.kind==='gym'){const w=gymWeek(data.shopVisits,jstDay(),data.gymGoal||2);return `<div class="shop-visit-panel gym-panel"><div class="shop-visit-heading"><strong>今週 ${w.count}/${w.goal} 回</strong><span>${w.done?'ノルマ達成':'あと'+w.left+'回'}</span></div><p>1回行くと${esc(data.pet.name)}の体型が ${SLIM_PER_VISIT} 引き締まる。${n?`これまで ${n}日。`:''}</p><div class="button-row"><button class="primary" data-visit="${esc(p.id)}" ${already?'disabled':''}>${already?'今日は記録済み':'今日来た'}</button><button class="secondary" data-action="edit-gym">ジムの位置を直す</button></div><div class="button-row"><button class="text-btn" data-action="gym-goal">週のノルマを変える（${w.goal}回）</button><button class="text-btn" data-visit-history="${esc(p.id)}">訪問履歴・修正</button></div></div>`;}return `<div class="shop-visit-panel"><div class="shop-visit-heading"><strong>${n}日訪問</strong><span>${frequent?'よく行くお店':'あと'+Math.max(0,3-n)+'日で自動追加'}</span></div><p>${esc(data.shopMemos[p.id]||p.defaultMemo||'このお店にひとことメモを付けられます。')}</p><div class="button-row"><button class="primary" data-visit="${esc(p.id)}" ${already?'disabled':''}>${already?'今日は記録済み':'今日来た'}</button><button class="secondary" data-frequent="${esc(p.id)}">${frequent?'よく行くから外す':'よく行くに登録'}</button></div><div class="button-row"><button class="text-btn" data-shop-memo="${esc(p.id)}">ひとことを編集</button><button class="text-btn" data-visit-history="${esc(p.id)}">訪問履歴・修正</button></div></div>`;}
function checkIn(id){if(!shops().some(p=>p.id===id))return;const old=frequentIds(),gymBefore=visitCount(data.shopVisits,GYM.id);data.shopVisits=mergeVisits(data.shopVisits,[{shopId:id,day:dayKey(Date.now()),time:Date.now(),source:'manual'}]);if(!save())return;gymEffect(gymBefore);openPlace(id);renderSidebar();toast(id===GYM.id?'ジムの訪問を記録。'+data.pet.name+'が少し引き締まった。':!old.includes(id)&&frequentIds().includes(id)?'「よく行くお店」に追加しました。':'今日の訪問を記録しました。');}
function gymEffect(before){const after=visitCount(data.shopVisits,GYM.id);if(after<=before)return;data.pet=slimMouse(data.pet,SLIM_PER_VISIT*(after-before));save();petMessage='ジムの日。少し引き締まった。';play('ting');}
function toggleFrequent(id){if(frequentIds().includes(id)){data.pinnedShops=data.pinnedShops.filter(x=>x!==id);data.dismissedShops=[...new Set([...data.dismissedShops,id])];}else{data.pinnedShops=[...new Set([...data.pinnedShops,id])];data.dismissedShops=data.dismissedShops.filter(x=>x!==id);}save();openPlace(id);renderSidebar();}
function editShopMemo(id){const p=shops().find(p=>p.id===id);if(!p)return;modal(`<h2>お店のひとこと</h2><p>${esc(p.title)}</p><form id="shop-memo-form"><label class="field">メモ<textarea name="memo" maxlength="180" placeholder="例：疲れた朝にさっとエネルギーチャージ。">${esc(data.shopMemos[id]||p.defaultMemo||'')}</textarea></label><button class="primary wide" type="submit">保存する</button></form>`);$('#shop-memo-form').onsubmit=e=>{e.preventDefault();data.shopMemos[id]=String(new FormData(e.target).get('memo')).trim();if(save()){closeModal();openPlace(id);renderSidebar();}};}
function visitHistory(id){const p=shops().find(p=>p.id===id);if(!p)return;const v=data.shopVisits.filter(v=>v.shopId===id).slice().reverse();modal(`<h2>訪問履歴</h2><p>${esc(p.title)}</p><p class="help-small">GPSの滞在検出は訪問の推定です。違う場合は削除できます。同じ日の訪問は1回にまとめています。</p>${v.length?v.map(v=>`<div class="visit-history-row"><span>${esc(v.day)}<small>${v.source==='gps'?'GPSで推定':'自分で記録'}</small></span><button class="text-btn" data-remove-visit="${esc(id+'|'+v.day)}">削除</button></div>`).join(''):'<p>まだ訪問記録がありません。</p>'}`);}
function removeVisit(key){const [id,day]=key.split('|');data.shopVisits=data.shopVisits.filter(v=>!(v.shopId===id&&v.day===day));save();visitHistory(id);renderSidebar();if(selected===id)openPlace(id);}
function trackShopStop(point,accuracy){if(!data.autoShops||!recording||recording.source!=='gps')return;const result=detectShopStop(shopCandidate,{point,time:point[2],accuracy},shops());shopCandidate=result.candidate;if(result.visit){recording.shopStops=mergeVisits(recording.shopStops||[],[result.visit]);persistDraft();toast(recording.auto?'お店での滞在を検出して保存しました。':'お店での滞在を検出しました。散歩の保存時に訪問を記録します。');}}
function editHome(){if(recording&&!recording.auto){toast('散歩の記録を保存してから位置を調整してください。');return;}closeDetail();hideMobile();goHome();modal(`<h2>自宅の位置を調整</h2><p>睦荘の公開地図をもとにピンを置いています。入口などに合わせたい場合は地図で位置を選べます。</p><button class="primary wide" id="pick-home">地図で場所を選ぶ</button>`);$('#pick-home').onclick=()=>{closeModal();toast('自宅の位置をタップしてください。');map.once('click',e=>{const pos=[e.latlng.lat,e.latlng.lng];if(!inKyoto(pos,boundary)){toast('京都府内の場所を選んでください。');return;}const preview=L.circleMarker(pos,{radius:11,color:'#fff',weight:3,fillColor:'#526c42',fillOpacity:1}).addTo(map);modal(`<h2>この位置を自宅にする</h2><p>ピンの位置を確認して保存してください。</p><div class="button-row"><button class="secondary" id="cancel-home">戻る</button><button class="primary" id="save-home">保存する</button></div>`);const clean=()=>map.removeLayer(preview);$('#dialog').addEventListener('close',clean,{once:true});$('#cancel-home').onclick=()=>{clean();closeModal();};$('#save-home').onclick=()=>{data.home={...home(),pos};if(save()){clean();closeModal();renderHomePin();goHome();renderSidebar();}};});};}
function validateVisitBackup(b){if(b.home!=null&&(!Array.isArray(b.home.pos)||b.home.pos.length!==2||b.home.pos.some(v=>typeof v!=='number'||!Number.isFinite(v))||!inKyoto(b.home.pos,boundary)))throw Error('自宅の位置が不正です');if(b.shopVisits!==undefined&&!validVisits(b.shopVisits))throw Error('お店の訪問記録の形式が不正です');for(const k of ['pinnedShops','dismissedShops'])if(b[k]!==undefined&&(!Array.isArray(b[k])||b[k].some(v=>typeof v!=='string'||v.length>160)))throw Error('お店の登録データが不正です');if(b.shopMemos!==undefined&&(!b.shopMemos||Array.isArray(b.shopMemos)||typeof b.shopMemos!=='object'||Object.values(b.shopMemos).some(v=>typeof v!=='string'||v.length>180)))throw Error('お店のメモが不正です');}

function goWork(){viewIntent++;map.flyTo(WORKPLACE.pos,16);$('#region').value='work';$('#location-status').textContent='銀くんの職場 · 至誠館4階（大学代表位置）';hideMobile();openPlace(WORKPLACE.id);}
function searchSupport(){return `<div class="search-support">${query.trim()?`<button class="secondary" data-action="search-online" ${remoteBusy?'disabled':''}>${remoteBusy?'施設を検索中…':'京都府の施設も検索'}</button><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query+' 京都府')}" target="_blank" rel="noopener noreferrer">Googleマップでも探す ↗</a><p>${esc(remoteMessage||'外部検索では検索語をPhotonに送信します。位置履歴は送りません。')}</p>`:'施設の別名・かな表記や、少し違う名前でも探せます。'}</div>`;}
async function searchOnline(){
 const q=query.trim();if(q.length<2){toast('施設名を2文字以上で入力してください。');return;}if(!boundary){toast('地図データを読み込み中です。');return;}if(remoteBusy||Date.now()-lastRemote<1300)return;
 remoteBusy=true;remoteQuery=q;remoteMessage='';remoteController=new AbortController();const controller=remoteController;const timeout=setTimeout(()=>controller.abort(),10000);renderListOnly();
 try{let result=searchCache.get(normalizeSearch(q));if(!result){lastRemote=Date.now();const config=await fetch('search-config.json').then(r=>r.json());const url=new URL(config.endpoint);url.search=new URLSearchParams({q,limit:'10',bbox:'134.85,34.68,136.05,35.81',lat:'35.04',lon:'135.78'});const response=await fetch(url,{signal:controller.signal});if(!response.ok)throw Error('検索サービスに接続できませんでした。');result=photonPlaces(await response.json(),p=>inKyoto(p,boundary));searchCache.set(normalizeSearch(q),result);}
  const ids=new Set(allPlaces().map(p=>p.id));let added=0;for(const p of result){if(ids.has(p.id))continue;if(places.some(known=>known.pos&&distance(known.pos,p.pos)<60&&(normalizeSearch(known.title).includes(normalizeSearch(p.title))||normalizeSearch(p.title).includes(normalizeSearch(known.title)))))continue;data.discoveredPlaces.push({...p,searchQueries:[q]});ids.add(p.id);added++;}if(added)save();remoteMessage=result.length?`京都府内の候補を${result.length}件取得しました。ピンは施設位置の目安です。`:'京都府内の候補がありません。地名を加えるかGoogleマップでも探せます。';
 }catch(error){remoteMessage=error.name==='AbortError'?'検索が中断されたか時間がかかっています。入力を確かめて再度お試しください。':'外部検索を利用できません。掲載済みの候補やGoogleマップから探せます。';}
 finally{clearTimeout(timeout);remoteBusy=false;if(query.trim()===q&&['explore','saved'].includes(tab)){renderListOnly();renderPins();}}
}
document.addEventListener('submit',e=>{if(e.target.id==='home-search'){e.preventDefault();const value=String(new FormData(e.target).get('q')||'').trim();browse();query=value;renderSidebar();renderPins();$('#search').focus();}});

function openLife(view){tab=view;closeDetail();renderSidebar();$('#sidebar-content').scrollTop=0;document.body.classList.add('mobile-show');}
function doPetCare(kind){updateMouse();const now=Date.now(),p=data.pet;
 if(p.travel.state!=='home'){petMessage='外出中。帰ってきたらお世話しよう。';renderSidebar();return;}
 if(isHiding(p,now)){if(kind==='brush'){pesterMouse('hidden');return;}data.pet=placeFood(p,now);save();petMessage=kind==='feed'?'皿にごはんを置いた。においで出てくるかもしれない。':'お水を置いた。';renderSidebar();return;}
 const candidates=places.filter(x=>x.pos&&['nature','history','shop'].includes(x.category)&&!x.encounter&&!x.oldReviews).sort((a,b)=>distance(a.pos,home().pos)-distance(b.pos,home().pos)).map(x=>x.id);
 const result=careMouse(p,kind,candidates,now);const previous=data.pet;data.pet=result.pet;if(!save()){data.pet=previous;return;}
 const moodAngry=angryUntil>now||mouseMood(previous,petStatus(previous,now),now).angry;let fx=null;
 if(result.unlocked){petMessage='散歩で見つけた場所を教えてくれた。';fx=kind;}
 else if(result.credited){petMessage={feed:'ぽりぽり食べている。',water:'お水を飲んだ。',brush:'目を細めている。'}[kind];fx=kind;if(kind==='feed'){angryUntil=0;}}
 else if(kind==='brush'){pesterMouse(moodAngry?'angry':'cooldown');return;}
 else petMessage='今は満足しているみたい。';
 renderSidebar();if(fx){$('.mouse-room')?.classList.add({feed:'eating',water:'drinking',brush:'happy'}[fx]);play({feed:'nibble',water:'plip',brush:'ting'}[fx]);}}
function pesterMouse(context){const r=pester(data.pet);const old=data.pet;data.pet=r.pet;if(!save()){data.pet=old;return;}
 if(r.level==='flee'){petMessage=context==='hidden'?'手を伸ばしたら、戸のすきまから逃げた。':context==='vacuum'?'掃除機ばかりで嫌になって、戸から出ていった。':'しつこくしたら逃げた。戸のすきまから出ていった。';angryUntil=0;play('door');}
 else if(r.level==='hide'){petMessage=context==='vacuum'?'掃除機が嫌で穴に隠れた。':'嫌がって穴に隠れた。しばらくそっとしておく。';angryUntil=0;}
 else if(r.level==='angry'){angryUntil=Date.now()+120000;petMessage=context==='vacuum'?'また掃除機。歯をむいている。':'しつこくなでたら歯をむいた。';}
 else petMessage=context==='angry'?'歯をむいて、手をよけた。':context==='vacuum'?'掃除機に慣れていない。':'今は満足しているみたい。';
 renderSidebar();}
function openGoat(message=''){modal(goatMarkup(data.goat,esc,message));}
function updateMouse(){const r=advanceMouse(data.pet);if(r.event){const old=data.pet;data.pet=r.pet;if(!save()){data.pet=old;return false;}petMessage=r.event==='return'?'帰ってきた。何食わぬ顔で座っている。'+(r.item?r.item+'を持っていた。':''):'いつの間にか外へ出かけた。';return true;}return false;}
setInterval(()=>{if(document.hidden||$('#dialog').open)return;if(updateMouse()&&['home','pet'].includes(tab))renderSidebar();},60000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&updateMouse()&&['home','pet'].includes(tab))renderSidebar();if(!document.hidden)maybeAutoGreet();});
document.addEventListener('submit',e=>{if(e.target.id!=='goat-vent-form')return;e.preventDefault();const input=e.target.elements.vent;if(!input.value.trim())return;input.value='';const old=data.goat;data.goat={paperCount:old.paperCount+1,updated:Date.now()};if(!save())data.goat=old;openGoat('もぐもぐ。おいしかった。');$('.workplace-goat')?.classList.add('eating');});
function editAnniversary(id){const a=data.anniversaries.find(x=>x.id===id);modal('<h2>'+(a?'記念日を編集':'記念日を登録')+'</h2><form id="anniversary-form"><label class="field">記念日の名前<input name="name" required maxlength="70" placeholder="交際記念日、銀くんの誕生日など" value="'+esc(a?.name||'')+'"></label><label class="field">最初の日付<input name="date" type="date" required value="'+(a?.date||jstDay())+'"></label><label class="field"><span><input type="checkbox" name="repeat" '+(a?.repeat!==false?'checked':'')+'> 毎年お祝いする</span></label><label class="field">ひとこと<textarea name="note" maxlength="300">'+esc(a?.note||'')+'</textarea></label><p class="pet-caption">2月29日の記念日は平年には2月28日で表示します。</p><button class="primary wide">保存する</button></form>');$('#anniversary-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),entry={id:a?.id||uid(),name:String(f.get('name')).trim(),date:String(f.get('date')),repeat:f.get('repeat')==='on',note:String(f.get('note')).trim(),updated:Date.now()};if(!validAnniversaries([entry]))return;const old=data.anniversaries;data.anniversaries=[...old.filter(x=>x.id!==id),entry];if(data.anniversaries.length>200){data.anniversaries=old;toast('記念日は200件まで登録できます。');return;}if(!save()){data.anniversaries=old;return;}closeModal();renderSidebar();};}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.anniversaryEdit)editAnniversary(b.dataset.anniversaryEdit);if(b.dataset.anniversaryDelete){const a=data.anniversaries.find(x=>x.id===b.dataset.anniversaryDelete);if(a)confirmAction('この記念日を削除？',a.name,()=>{data.anniversaries=data.anniversaries.filter(x=>x.id!==a.id);save();renderSidebar();});}if(b.dataset.anniversaryIcs){const a=data.anniversaries.find(x=>x.id===b.dataset.anniversaryIcs);if(a)download('anniversary-'+a.id+'.ics',anniversaryIcs(a),'text/calendar;charset=utf-8');}});
function autoHome(){const on=!!recording?.auto;return '<div class="auto-record-card"><span><strong>'+(!data.autoTrackConsent?'道を自動で残す':on?'道を自動保存中':'自動記録は停止中')+'</strong>'+(on?esc(recording.status):'画面を開いている間の道を保存します。')+'</span><button data-action="toggle-auto-track">'+(on?'止める':'はじめる')+'</button></div>';}
function checkpointAuto(){if(!recording?.auto)return true;const before=data.walks,visits=data.shopVisits,gymBefore=visitCount(data.shopVisits,GYM.id);data.walks=commitAutoWalk(data.walks,recording);data.shopVisits=mergeVisits(data.shopVisits,recording.shopStops||[]);if(!save()){data.walks=before;data.shopVisits=visits;stopGps();recording.paused=true;recording.status='保存できないため停止しました。記録はまだ画面内にあります。';renderRecordBar();return false;}renderHeat();gymEffect(gymBefore);if(!recording.mouseChecked&&pathLength(recording.points)>=800){recording.mouseChecked=true;mouseOnWalk(pathLength(recording.points)/1000);}return true;}
function startAutoTrack(){if(recording||!boundary||!data.autoTrackConsent)return;recording=resumeAutoWalk(data.walks);gpsLast=null;gpsBreak=true;shopCandidate=null;demo=false;renderRecordBar();startGps();}
function toggleAutoTrack(){if(recording&&!recording.auto){toast('手動の記録を保存してから切り替えてください。');return;}if(recording?.auto){if(!checkpointAuto())return;data.autoTrack=false;save();endRecord();closeModal();renderSidebar();toast('ここまで保存して自動記録を止めました。');return;}if(!boundary){toast('地図データの読み込み後にもう一度お試しください。');return;}data.autoTrack=true;data.autoTrackConsent=true;if(!save())return;closeModal();startAutoTrack();renderSidebar();}

